/// <summary>
/// Finds a record
/// </summary>
/// <param name = "_inventTable">_inventTable</param>
/// <param name = "_update">true or false</param>
/// <returns>Record</returns>
static public NDXMultipleS_smmBusRelChainGroup find(InventTable _inventTable, boolean _update = false)
{
    NDXMultipleS_smmBusRelChainGroup lNDXMultipleS_smmBusRelChainGroup;

    if(_inventTable)
    {
        lNDXMultipleS_smmBusRelChainGroup.selectForUpdate(_update);

        select lNDXMultipleS_smmBusRelChainGroup
            where lNDXMultipleS_smmBusRelChainGroup.RefRecId_InventTable == _inventTable.RecId;
    }

    return lNDXMultipleS_smmBusRelChainGroup;
}

/// <summary>
/// Check if check is available
/// </summary>
/// <param name = "_inventTable">_inventTable</param>
/// <returns>true or false</returns>
static public boolean hasValidityCheck(InventTable _inventTable)
{
    return NDXMultipleS_smmBusRelChainGroup::find(_inventTable).RecId > 0;
}

/// <summary>
/// Return all validation chain group ids for the item as string
/// </summary>
/// <param name = "_itemRecId">_itemRecId</param>
/// <returns>String of chain group ids</returns>
static str Range2String(RecId _itemRecId)
{
    #define.Comma(' ,')

    NDXMultipleS_smmBusRelChainGroup     nDX_MultipleS_Chain;
    smmBusRelChainGroup smmBusRelChainGroup;

    str        range2String;
    boolean                 lFirst = true;
    ;
    while select nDX_MultipleS_Chain
        where    nDX_MultipleS_Chain.RefRecId_InventTable == _itemRecId
        join smmBusRelChainGroup
            where smmBusRelChainGroup.RecId == nDX_MultipleS_Chain.RefRecId_smmBusRelChainGroup
    {
        if (!lFirst)
        {
            range2String += #Comma;
        }
        else
        {
            lFirst = false;
        }

        range2String += smmBusRelChainGroup.ChainId;
    }
    return range2String;
}

public void insert()
{
    NDXMultipleS_smmBusRelChainGroup orig = this.orig();
    super();
    this.writeLog(orig, this);
}

public void update()
{
    NDXMultipleS_smmBusRelChainGroup orig = this.orig();
    super();
    this.writeLog(orig, this);
}

public void delete()
{
    NDXMultipleS_smmBusRelChainGroup orig = this.orig();
    super();
    this.writeLog(orig, null);
}

/// <summary>
/// Writes a log for record change
/// </summary>
/// <param name = "_orig">record before</param>
/// <param name = "_current">record after</param>
private void writeLog(NDXMultipleS_smmBusRelChainGroup _orig, NDXMultipleS_smmBusRelChainGroup _current)
{
    NDXMultipleS_Log   multipleS_Log;

    if(!_current)
    {
        multipleS_Log.RefRecIdInventTable = _orig.RefRecId_InventTable;
    }
    else
    {
        multipleS_Log.RefRecIdInventTable = _current.RefRecId_InventTable;
    }

    if (_orig.RefRecId_smmBusRelChainGroup != _current.RefRecId_smmBusRelChainGroup)
    {
        multipleS_Log.ValidityCheckType = NDXValidityCheckType::Chain;

        multipleS_Log.RangeValue        =  smmBusRelChainGroup::findByRecId(_current.RefRecId_smmBusRelChainGroup).ChainId;

        if (!_orig.RefRecId_smmBusRelChainGroup)            // Neuanlage
        {
            multipleS_Log.ChangeType        = NDXChangeType::New;
        }
        else if (!_current.RefRecId_smmBusRelChainGroup) // Löschung
        {
            multipleS_Log.RangeValue        = smmBusRelChainGroup::findByRecId(_orig.RefRecId_smmBusRelChainGroup).ChainId;
            multipleS_Log.ChangeType        = NDXChangeType::Delete;
        }
        else                                // Änderung
        {
            multipleS_Log.RangeValue        += strFmt("@ApplicationFoundation:DocuDeletedRefCaptionGeneratorFromLabel", smmBusRelChainGroup::findByRecId(_orig.RefRecId_smmBusRelChainGroup).ChainId);
            multipleS_Log.ChangeType        = NDXChangeType::Update;
        }
        multipleS_Log.insert();
    }

}
